      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Reported hospital symptoms and patient's view of recent illness"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Hospital discharge summary reportedly recorded fever and confusion during the recent admission. Patient disputes the sepsis diagnosis and describes the illness as a bad flu and dehydration."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Blood culture results"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Two blood cultures: no growth, per hospital discharge information dated 20/11."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "White blood cell count"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "18, decreasing to 10.2 at discharge, per hospital discharge information dated 20/11; units not provided."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "Creatinine"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 83
        },
        "note": [
          {
            "text": "Per hospital discharge information dated 20/11; units not provided."
          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "C-reactive protein"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Downtrending per hospital discharge information dated 20/11; exact value not provided."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "General examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Alert, mildly irritable and animated, occasionally raised voice, sitting comfortably."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-16",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-16",
        "status": "final",
        "code": {
          "text": "ENT examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Nasal mucosa mildly erythematous and oedematous with clear rhinorrhoea; no sinus tenderness. Oropharynx mildly erythematous with no exudate. Neck supple with no significant cervical lymphadenopathy."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-17",
