        "resourceType": "Observation",
        "id": "observation-17",
        "status": "final",
        "code": {
          "text": "Respiratory examination"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Normal work of breathing; mild bibasal crackles, right greater than left. No focal bronchial breathing or wheeze; good air entry bilaterally."
      }
