          }
        ]
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationRequest/medication-request-1",
      "resource": {
        "resourceType": "MedicationRequest",
        "id": "medication-request-1",
        "status": "active",
        "intent": "order",
        "medicationCodeableConcept": {
          "text": "Fluticasone 50 mcg intranasal spray"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosageInstruction": [
          {
            "text": "2 sprays into each nostril every morning for 7 days, then reduce to 1 spray into each nostril every morning for a further week if beneficial.",
            "route": {
              "text": "intranasal"
            },
            "timing": {
